 ok(await page.evaluate(async()=>(await caches.keys()).some(k=>/^marine-tools-app-preview-0\.2\.0-[a-f0-9]{16}$/.test(k))),'Offline package cache is versioned by asset contents');
 upgradeWorker=true;await page.evaluate(async()=>{localStorage.setItem('mt.app.qa.upgrade','retained');const r=await navigator.serviceWorker.getRegistration();await r.update()});await page.locator('#mt-app-update').waitFor({state:'visible'});const upgrading=page.waitForNavigation();await page.locator('#mt-app-update').click();await upgrading;await page.waitForFunction(()=>!!window.MT_APP_NAV);ok(await page.evaluate(()=>localStorage.getItem('mt.app.qa.upgrade'))==='retained','User-applied worker update preserves local work');
