 server.closeAllConnections();await new Promise(r=>server.close(r));server=null;await page.evaluate(()=>window.__beforeOfflineNavigation=true);let offlineNavigationError='';await page.goto(base+'/index.html?offline-check=1').catch(e=>{offlineNavigationError=e.message});await page.waitForFunction(()=>window.MT_APP_PREVIEW&&!window.__beforeOfflineNavigation&&!!window.MT_APP_NAV&&document.readyState==='complete');await page.evaluate(()=>__marineToolsOpenPage('vessel-calcs'));await page.locator('#calcAirDraft').click();ok(/3[.,]20 m remaining clearance/.test(await page.locator('#resAirDraft').textContent()),'Fresh offline navigation retains working calculator');
 await context.setOffline(true);await page.setViewportSize({width:390,height:844});ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2),'Mobile package fits screen');await page.screenshot({path:path.join(out,'offline-mobile.png'),fullPage:true,animations:'disabled'});
